package com.clinic.appointment.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="prescription_items") public class PrescriptionItem{@Id private UUID id;@Column(nullable=false)private UUID appointmentId;@Column(nullable=false)private String medication;@Column(nullable=false)private String instructions;@Column(nullable=false)private int intervalHours;@Column(nullable=false)private int durationDays;@Column(nullable=false)private Instant createdAt;protected PrescriptionItem(){}public PrescriptionItem(UUID appointment,String medication,String instructions,int hours,int days){id=UUID.randomUUID();appointmentId=appointment;this.medication=medication;this.instructions=instructions;intervalHours=hours;durationDays=days;createdAt=Instant.now();}public String getMedication(){return medication;}public String getInstructions(){return instructions;}public int getIntervalHours(){return intervalHours;}public int getDurationDays(){return durationDays;}}
